app/seo-config.ts:
  'airport-glance': {ko:shareDescription,en:'Check Incheon Airport departures and arrivals, hourly passenger forecasts, route-country passenger trends, exchange rates and arrival allowances. Source dates and references accompany the data.',zh:'一览仁川机场T1主楼、卫星厅和T2的出发航班、目的地及官方出境区等候。按所选日期查看各国航班比例、上月日均比较和未来时段航班集中的区域，并区分航班数量与旅客人数。',ja:'仁川空港のT1本館・搭乗棟・T2の出発便、目的地と公式出国場の待ち時間を一覧で確認できます。選択日の国別便数の割合、前月の日平均との比較、今後の出発便が集中するエリアを、旅客数と区別して表示します。'},
  airport: { ko: "인천공항 전체·T1·T2의 출국장 공식 예상 출국객과 피크, 실제 출발 운항과 집중 게이트, 현재 출국장 대기, 월별 공식 실적을 확인하세요.", en: "Official departure-hall passenger forecast and peak, physical departing flights and busiest gates, current departure-hall waits and official monthly history for all terminals, T1 and T2.", zh: "查看仁川机场整体、T1、T2的出境大厅官方预计人数与高峰、实际出发航班与集中登机口、当前出境区等候，以及月度官方实绩。", ja: "仁川空港全体・T1・T2の出国場公式予想旅客とピーク、実出発便と集中ゲート、現在の出国場待ち、月次公式実績を確認できます。" },
  predictions: { ko: "서울시 공식 예측으로 앞으로 가장 붐빌 시간을 확인하고, 명동·홍대·성수·이태원의 내일 인구 흐름 참고 예상과 최근 28일 관측 기록이 얼마나 쌓였는지 함께 보세요.", en: "See the busiest hour ahead in Seoul's official forecast, KORETAIL's reference outlook for tomorrow in Myeongdong, Hongdae, Seongsu and Itaewon, and how much of the last 28 days is actually on record.", zh: "通过首尔市官方预测查看未来最拥挤的时段，并了解明洞、弘大、圣水、梨泰院明日人口趋势的参考预测，以及最近28天观测记录的累积情况。", ja: "ソウル市公式予測で今後最も混雑する時間を確認し、明洞・弘大・聖水・梨泰院の明日の人口の流れの参考予測と、直近28日の観測記録の蓄積状況を合わせて確認できます。" },
  forecast: { ko: "각 지표가 무엇을 뜻하는지, 높으면 어떤 상황인지, 어떤 공식 자료에서 왔는지를 설명과 함께 확인하세요. T1·T2 비중과 지역 외국인 생활인구 흐름을 포함합니다.", en: "Every figure with what it means, what a high value indicates and which official record it came from — including T1/T2 share and area foreign-population history.", zh: "每个指标都附含义、数值偏高时的情况与官方出处说明，包含T1/T2占比与各地区外国人生活人口趋势。", ja: "各指標の意味・高いときの状況・出典を説明付きで確認できます。T1・T2の比率とエリア別外国人生活人口の推移を含みます。" },
  business: { ko: "인천공항 흐름과 업종별 점검 목록을 확인하세요. 일반 운영 안내이며 매출이나 방문객 수를 예측하지 않습니다.", en: "Review Incheon Airport flows and industry checklists. General operating guidance, not a sales or visitor forecast.", zh: "按航站楼查看仁川机场客流与各业态检查清单，并确认资料基准时间。此为一般运营指南，不预测销售额或访客人数。", ja: "仁川空港の動向と業種別チェックリストを確認できます。一般的な運営案内であり、売上や来訪者数の予測ではありません。" },
  about: { ko: "인천공항 항공편·여객 흐름과 여행 준비 정보를 제공하는 코리테일을 소개합니다. 자료의 출처와 기준일, 관측·예상·과거 기록의 차이를 안내합니다.", en: "What KORETAIL is, who it is for, which official data it uses, and how live, forecast and past data differ.", zh: "介绍 KORETAIL 是什么、面向哪些人、使用哪些官方数据，以及实时、预测与历史数据的区别。", ja: "KORETAIL とは何か、誰のためのサービスか、どの公式データを使うか、リアルタイム・予測・過去データの違いを説明します。" },
  more: { ko: "KORETAIL의 데이터 출처, 무료·키 필요 여부, Demo·공식 이력 구분, 예측 방법론과 데이터 상태를 확인하세요.", en: "Review KORETAIL data sources, access conditions, Demo/official-history labels, methodology and data health.", zh: "查看 KORETAIL 使用的数据来源、各来源是否免费或需要密钥、演示数据与官方历史记录的区分方式，以及预测方法论与当前数据状态。", ja: "KORETAILのデータ出典、接続条件、デモ・公式履歴の区別、方法論、データ状況を確認できます。" },
};
return descriptions[slug as Exclude<SeoSlug, keyof typeof names | "tourism-desk">][locale];
